// Formatting library for C++ - formatters for standard library types
//
// Copyright (c) 2012 - present, Victor Zverovich
// All rights reserved.
//
// For the license information refer to format.h.

#ifndef FMT_STD_H_
#define FMT_STD_H_

#include <atomic>
#include <bitset>
#include <cstdlib>
#include <exception>
#include <memory>
#include <thread>
#include <type_traits>
#include <typeinfo>
#include <utility>
#include <vector>

#include "format.h"
#include "ostream.h"

#if FMT_HAS_INCLUDE(<version>)
#  include <version>
#endif
// Checking FMT_CPLUSPLUS for warning suppression in MSVC.
#if FMT_CPLUSPLUS >= 201703L
#  if FMT_HAS_INCLUDE(<filesystem>)
#    include <filesystem>
#  endif
#  if FMT_HAS_INCLUDE(<variant>)
#    include <variant>
#  endif
#  if FMT_HAS_INCLUDE(<optional>)
#    include <optional>
#  endif
#endif

// GCC 4 does not support FMT_HAS_INCLUDE.
#if FMT_HAS_INCLUDE(<cxxabi.h>) || defined(__GLIBCXX__)
#  include <cxxabi.h>
// Android NDK with gabi++ library on some architectures does not implement
// abi::__cxa_demangle().
#  ifndef __GABIXX_CXXABI_H__
#    define FMT_HAS_ABI_CXA_DEMANGLE
#  endif
#endif

// Check if typeid is available.
#ifndef FMT_USE_TYPEID
// __RTTI is for EDG compilers. In MSVC typeid is available without RTTI.
#  if defined(__GXX_RTTI) || FMT_HAS_FEATURE(cxx_rtti) || FMT_MSC_VERSION || \
      defined(__INTEL_RTTI__) || defined(__RTTI)
#    define FMT_USE_TYPEID 1
#  else
#    define FMT_USE_TYPEID 0
#  endif
#endif

// For older Xcode versions, __cpp_lib_xxx flags are inaccurately defined.
#ifndef FMT_CPP_LIB_FILESYSTEM
#  ifdef __cpp_lib_filesystem
#    define FMT_CPP_LIB_FILESYSTEM __cpp_lib_filesystem
#  else
#    define FMT_CPP_LIB_FILESYSTEM 0
# endif
#endif

#ifndef FMT_CPP_LIB_VARIANT
#  ifdef __cpp_lib_variant
#    define FMT_CPP_LIB_VARIANT __cpp_lib_variant
#  else
#    define FMT_CPP_LIB_VARIANT 0
#  endif
#endif

#if FMT_CPP_LIB_FILESYSTEM
FMT_BEGIN_NAMESPACE

FMT_EXPORT
template <typename Char> struct formatter<std::filesystem::path, Char> {
 private:
  format_specs<Char> specs_;
  detail::arg_ref<Char> width_ref_;
  bool debug_ = false;

 public:
  FMT_CONSTEXPR void set_debug_format(bool set = true) { debug_ = set; }

  template <typename ParseContext> FMT_CONSTEXPR auto parse(ParseContext& ctx) {
    auto it = ctx.begin(), end = ctx.end();
    if (it == end) return it;

    it = detail::parse_align(it, end, specs_);
    if (it == end) return it;

    it = detail::parse_dynamic_spec(it, end, specs_.width, width_ref_, ctx);
    if (it != end && *it == '?') {
      debug_ = true;
      ++it;
    }
    return it;
  }

  template <typename FormatContext>
  auto format(const std::filesystem::path& p, FormatContext& ctx) const {
    int width = specs_.width;
    detail::handle_dynamic_spec<detail::width_checker>(width, width_ref_, ctx);
    return write_path(p, p.native(), width, ctx.out());
  }

 private:
  template <typename PathChar>
  static auto convert_escaped_wide(const std::basic_string<PathChar>& escaped)
      -> std::string {
    memory_buffer quoted;
    bool valid = detail::to_utf8<wchar_t>::convert(
        quoted, {escaped.data(), escaped.size()});
    FMT_ASSERT(valid, "invalid utf16");
    return std::string(quoted.data(), quoted.size());
  }

  template <typename PathChar, typename OutputIt>
  auto write_path(const std::filesystem::path& p,
                  const std::basic_string<PathChar>& native, int width,
                  OutputIt out) const -> OutputIt {
    auto specs = specs_;
    specs.width = width;
    std::basic_string<Char> rendered;
    if (!p.empty() && native.size() != 0) {
      if (!debug_) {
        if constexpr (std::is_same_v<Char, char> &&
                      std::is_same_v<PathChar, wchar_t>) {
          rendered = std::string(detail::to_utf8<wchar_t>(
              basic_string_view<PathChar>(native.data(), native.size()),
              detail::to_utf8_error_policy::replace));
        } else if constexpr (std::is_same_v<Char, PathChar>) {
          rendered.assign(native.data(), native.size());
        } else {
          rendered = p.string<Char>();
        }
      } else if constexpr (std::is_same_v<Char, char> &&
                           std::is_same_v<PathChar, wchar_t>) {
        std::basic_string<wchar_t> escaped;
        detail::write_escaped_string<wchar_t>(
            std::back_inserter(escaped),
            basic_string_view<PathChar>(native.data(), native.size()));
        rendered = convert_escaped_wide(escaped);
      } else if constexpr (std::is_same_v<Char, PathChar>) {
        detail::write_escaped_string<PathChar>(
            std::back_inserter(rendered),
            basic_string_view<PathChar>(native.data(), native.size()));
      } else {
        detail::write_escaped_string<Char>(std::back_inserter(rendered),
                                           p.string<Char>());
      }
    }
    const Char* data = rendered.data();
    size_t size = rendered.size();
    if (specs.precision >= 0 && detail::to_unsigned(specs.precision) < size) {
      size = detail::code_point_index(basic_string_view<Char>(data, size),
                                      detail::to_unsigned(specs.precision));
    }
    size_t display_width = 0;
    if (specs.width != 0) {
      display_width =
          detail::compute_width(basic_string_view<Char>(data, size));
    }
    unsigned spec_width = detail::to_unsigned(specs.width);
    size_t padding = spec_width > display_width ? spec_width - display_width : 0;
    auto* shifts = "\x1f\x1f\x00\x01";
    size_t left_padding = padding >> shifts[specs.align];
    size_t right_padding = padding - left_padding;
    auto fill_size = specs.fill.size();
    const Char* fill_data = specs.fill.data();
    auto it = detail::reserve(out, size + padding * fill_size);
    auto apply_fill = [&](auto out_it, size_t count) {
      if (fill_size == 1) return detail::fill_n(out_it, count, fill_data[0]);
      for (size_t i = 0; i < count; ++i)
        out_it = detail::copy_str<Char>(fill_data, fill_data + fill_size, out_it);
      return out_it;
    };
    if (left_padding != 0) it = apply_fill(it, left_padding);
    it = detail::copy_str<Char>(data, data + size, it);
    if (right_padding != 0) it = apply_fill(it, right_padding);
    return detail::base_iterator(out, it);
  }
};
FMT_END_NAMESPACE
#endif // FMT_CPP_LIB_FILESYSTEM

